create('test/greet.test.ts', r'''import { strict as assert } from 'node:assert'
import { test } from 'node:test'
import { DEFAULT_NAME, greet } from '../src/index.ts'

test('greet defaults to world', () => {
  assert.equal(DEFAULT_NAME, 'world')
  assert.equal(greet(), 'Hello, world!')
})

test('greet uses the given name verbatim', () => {
  assert.equal(greet('Ada'), 'Hello, Ada!')
  assert.equal(greet('Grace Hopper'), 'Hello, Grace Hopper!')
})

test('greet rejects blank names with TypeError', () => {
  for (const blank of ['', ' ', '\t\n']) {
    assert.throws(() => greet(blank), TypeError)
  }
})

test('greet rejects non-string input from untyped callers', () => {
  assert.throws(() => greet(42 as unknown as string), TypeError)
})
''')
create('test/cli.test.ts', r'''import { strict as assert } from 'node:assert'
import { spawnSync } from 'node:child_process'
import { test } from 'node:test'
import { fileURLToPath } from 'node:url'

const CLI = fileURLToPath(new URL('../src/cli.ts', import.meta.url))

function cli(...args: string[]) {
  return spawnSync(process.execPath, [CLI, ...args], { encoding: 'utf8' })
}

test('cli prints the default greeting', () => {
  const result = cli()
  assert.equal(result.status, 0)
  assert.equal(result.stdout, 'Hello, world!\n')
})

test('cli greets a named user', () => {
  const result = cli('Ada')
  assert.equal(result.status, 0)
  assert.equal(result.stdout, 'Hello, Ada!\n')
})

test('cli --help and -h exit 0 with usage', () => {
  for (const flag of ['--help', '-h']) {
    const result = cli(flag)
    assert.equal(result.status, 0)
    assert.match(result.stdout, /^Usage: greenfield-proof \[name\] \[--help\]/)
  }
})

test('cli rejects unknown options with exit 1 and usage', () => {
  const result = cli('--bogus')
  assert.equal(result.status, 1)
  assert.equal(result.stdout, '')
  assert.match(result.stderr, /Unknown option: --bogus/)
  assert.match(result.stderr, /Usage: greenfield-proof/)
})

test('cli unknown options exit 1 even when combined with a help option', () => {
  for (const args of [['--help', '--bogus'], ['--bogus', '--help'], ['-h', '--bogus'], ['--bogus', '-h']]) {
    const result = cli(...args)
    assert.equal(result.status, 1)
    assert.equal(result.stdout, '')
    assert.match(result.stderr, /Unknown option: --bogus/)
    assert.match(result.stderr, /Usage: greenfield-proof/)
  }
})

test('cli rejects a blank name with exit 1 and usage', () => {
  const result = cli('   ')
  assert.equal(result.status, 1)
  assert.equal(result.stdout, '')
  assert.match(result.stderr, /non-blank/)
  assert.match(result.stderr, /Usage: greenfield-proof/)
})
''')
